\label{lem:dice-string}
A set of dice is permutation-fair if and only if its string representation is
permutation-fair.

\label{lem:partial}
Let \(s\) be \(n\)-fair, let \(C\) be the common count of a full pattern, and
let \(c_i=C_i(s)\).  If \(\pi\in\mathop{\Pi}_{n,k}\) uses the set \(S\subseteq[n]\),
then
\begin{equation}\label{eq:partial-count}
  C_\pi(s)
  =\frac{(n!/k!)C}{\prod_{\ell\notin S}c_\ell}.
\end{equation}

\label{cor:self-concat}
If \(s\) is \(n\)-fair, then \(s\mathbin{\circ} s\), and hence every positive power
\(s^m\), is \(n\)-fair.

\label{lem:equal-full-to-partial}
If \(s\) is \(n\)-fair and every letter occurs equally often, then \(s\) is
\((\leq n,n)\)-fair.

\label{lem:symmetrize}
Let \(k<n\).  From any \((\leq k,n)\)-fair string \(s\) of length \(\ell\), one
can construct a \((\leq k+1,n)\)-fair string of length \(\ell n!\).

\label{lem:insertion}
If
\begin{equation}\label{eq:insertion-moments}
  \sum_{i=0}^N w_i b_{r,j}(i/N)=\frac1{r+1}
  \qquad(0\leq j\leq r),
\end{equation}
then the string \(T\) in~\eqref{eq:interlace} is \((r+1)\)-fair.

\label{lem:Q-supnorm}
For every \(0\leq k\leq n\) and every integer \(i\in\{0,\ldots,N\}\),
\begin{equation}\label{eq:Q-supnorm}
  |Q_k(i)|\leq1.
\end{equation}

\label{lem:wilson-integral}
Let \(N\geq1\), let \(0\leq k\leq N\), and let \(Q_k\) and \(I_k\) be as
above.  If \(k\) is odd, then \(I_k=0\).  If \(k\geq2\) is even and
\(N+1\geq(k+1)^2\), then
\begin{equation}\label{eq:I-wilson}
  0<-I_k\leq\frac{N+1}{N}
  \left(1+\frac{(k-1)(k+2)}{4(N-1)}\right).
\end{equation}
Consequently, for the choice \(N=n(n+2)\),
\begin{equation}\label{eq:I-bound}
  |I_k|<\frac32\qquad(1\leq k\leq n).
\end{equation}

\label{prop:quadrature}
The weights \(W_0,\ldots,W_N\) are strictly positive and satisfy
\begin{equation}\label{eq:quadrature-N}
  \sum_{i=0}^NW_ip(i)=\int_0^Np(x)\,dx
  \qquad\text{for every polynomial \(p\) with \(\deg p\leq n\)}.
\end{equation}
Moreover, \(\sum_iW_i=N\).

\label{thm:main}
For every \(n\geq1\), there are \(n\) equal-sided permutation-fair dice
with \(F_n\) faces each, where, for \(N=n(n+2)\),
\begin{equation}\label{eq:F-explicit}
  \boxed{\begin{aligned}
  F_n={}&(N+1)\operatorname{lcm}(1,\ldots,n+1)N^{\underline{n}}\\
        &{}\cdot(N+2)(N+3)\cdots(N+n+1)N^{n-1}.
  \end{aligned}}
\end{equation}
In particular,
\[
  F_n=2^{O(n\log n)}.
\]
The corresponding string is \((\leq n,n)\)-fair.

\label{individual-quadrature-facts}
The \(D\)-node Gaussian rule has positive weights, is exact through
degree \(2D-1\), and has largest node \(\xi_D\) satisfying
\begin{equation}\label{individual-gaussian-edge}
  1-\xi_D\leq\frac{\pi^2}{4(D+1)^2}.
\end{equation}
The right Radau rule with interior nodes \(t_1<\cdots<t_e\) and endpoint
\(1\) has positive weights and is exact through degree \(2e\).  Its
endpoint weight and interior nodes satisfy
\begin{equation}\label{individual-radau-identities}
  \omega_{\mathrm{end}}=\frac1{(e+1)^2},
  \qquad
  \sum_{\ell=1}^e\frac1{1-t_\ell}=\frac{e(e+2)}2.
\end{equation}
